package de.lazytv.pro.catalog; import android.content.Context; import de.lazytv.pro.playlist.*; public class CatalogEngine {private final StalkerCatalogSource stalker=new StalkerCatalogSource(); public Catalog load(Context c,Playlist p)throws CatalogException{String e=PlaylistValidator.validateForConnect(c,p);if(e!=null)throw new CatalogException(e);switch(p.getType()){case M3U_URL:case M3U_FILE:return new M3uCatalogSource().load(c,p);case XTREAM_CODES:return new XtreamCatalogSource().load(p);case STALKER_PORTAL:return stalker.load(p);default:throw new CatalogException("Lloj burimi i panjohur");}}public SeriesDetails loadSeries(Playlist p,Series s)throws CatalogException{if(p.getType()==PlaylistType.XTREAM_CODES)return new XtreamCatalogSource().loadSeries(p,s.id);if(p.getType()==PlaylistType.STALKER_PORTAL)return stalker.loadSeries(p,s);throw new CatalogException("Ky burim nuk ekspozon seasons/episodes të strukturuara");}public ResolvedStream resolveStream(Playlist p,StreamItem i)throws CatalogException{return new StreamResolver(stalker).resolve(p,i);} public ResolvedStream refreshStream(Playlist p,StreamItem i)throws CatalogException{if(p.getType()==PlaylistType.STALKER_PORTAL)stalker.clear();return resolveStream(p,i);} public void close(){stalker.clear();}}
